// ===========================================
// ICP INTERPRETER - LUSHA API COMPATIBLE
// ===========================================
// Converts form inputs to Lusha API format with correct ID mappings

const formData = $input.first().json;

// ----- SENIORITY MAPPING (Label → String ID) -----
const seniorityMap = {
  "Founder": "10",
  "C-Suite": "9",
  "VP / Vice President": "8",
  "Partner": "7",
  "Director": "6",
  "Manager": "5",
  "Senior": "4",
  "Entry": "3",
  "Intern": "2"
};

// ----- INDUSTRY MAPPING (Label → mainIndustriesIds) -----
const industryMap = {
  "Technology & Software": 17,
  "Finance & Banking": 9,
  "Business Services & Consulting": 14,
  "Healthcare": 11,
  "Manufacturing": 12,
  "Retail & E-Commerce": 16,
  "Real Estate": 15,
  "Education": 6,
  "Hospitality": 1,
  "Construction": 3,
  "Government": 10,
  "Transportation & Logistics": 18
};

// ----- DEPARTMENT MAPPING (Label → Lusha API value) -----
const departmentMap = {
  "C-Suite / Executive": "C-Suite",
  "Operations": "Operations",
  "IT / Technology": "Information Technology",
  "Marketing": "Marketing",
  "Sales": "Sales",
  "Finance": "Finance",
  "Engineering & Technical": "Engineering & Technical",
  "Human Resources": "Human Resources"
};

// ----- PARSE FORM INPUTS -----

// Industries
let industriesInput = formData['Industry'] || [];
if (typeof industriesInput === 'string') {
  industriesInput = industriesInput.split(',').map(i => i.trim());
}
const mainIndustriesIds = industriesInput
  .map(label => industryMap[label])
  .filter(id => id !== undefined);

// Departments
let departmentsInput = formData['Department'] || [];
if (typeof departmentsInput === 'string') {
  departmentsInput = departmentsInput.split(',').map(d => d.trim());
}
const departments = departmentsInput
  .map(label => departmentMap[label] || label)
  .filter(d => d);

// Seniority
let seniorityInput = formData['Seniority Level'] || [];
if (typeof seniorityInput === 'string') {
  seniorityInput = seniorityInput.split(',').map(s => s.trim());
}
const seniorityIds = seniorityInput
  .map(label => seniorityMap[label])
  .filter(id => id !== undefined);

// Location
const country = formData['Country'] || 'United States';
const city = formData['City (Optional)'] || '';

// Company size
const companySizeMin = parseInt(formData['Company Size (Min Employees)'] || '1');
const companySizeMax = parseInt(formData['Company Size (Max Employees)'] || '10000');

// Page size & scoring
const pageSize = parseInt(formData['Number of Leads'] || '25');
const minScore = parseInt(formData['Minimum Score for Qualified (1-10)'] || '6');
const icpDescription = formData['Target ICP Description'] || '';

// ----- BUILD LOCATION OBJECT -----
const locationFilter = { country: country };
if (city) {
  locationFilter.city = city;
}

// ----- BUILD LUSHA API REQUEST BODY -----
const lushaRequestBody = {
  pages: {
    page: 0,
    size: pageSize
  },
  filters: {
    contacts: {
      include: {
        departments: departments,
        seniority: seniorityIds,
        locations: [locationFilter],
        existing_data_points: ["work_email"]
      }
    },
    companies: {
      include: {
        mainIndustriesIds: mainIndustriesIds,
        sizes: [
          {
            min: companySizeMin,
            max: companySizeMax
          }
        ]
      }
    }
  }
};

// ----- OUTPUT -----
return {
  json: {
    lushaRequestBody: lushaRequestBody,
    config: {
      industries: industriesInput,
      mainIndustriesIds: mainIndustriesIds,
      departments: departments,
      seniorityLevels: seniorityInput,
      seniorityIds: seniorityIds,
      country: country,
      city: city,
      companySizeMin: companySizeMin,
      companySizeMax: companySizeMax,
      pageSize: pageSize,
      minScore: minScore,
      icpDescription: icpDescription
    },
    debugInfo: {
      rawFormData: formData,
      mappedIndustries: mainIndustriesIds,
      mappedSeniority: seniorityIds,
      mappedDepartments: departments
    }
  }
};

